contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newOwner) public payable {
        address oldOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool success = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        address currentOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(
            success &&
            currentOwner == newOwner &&
            (newOwner != oldOwner ? currentOwner == newOwner : currentOwner == oldOwner)
        );
    }

    receive() external payable {}
}

